// WF-3 guard — validate state has candidate
const state = $input.first().json;
if (!state || state.schema_version !== 1) throw new Error(`WF-3: invalid schema_version ${JSON.stringify(state?.schema_version)}`);
if (!state.candidate || !state.candidate.code) throw new Error('WF-3: candidate.code missing');
return [{ json: state }];

// WF-3 Security prompt builder
const state = $input.first().json;
let system = '';
try { system = require('fs').readFileSync('/prompts/audit_security_system.md','utf8'); } catch(e) { system = 'You are the Security Agent. Output JSON {security_pass, objections}.'; }
const prompt = system + "

Candidate code:
```python
" + state.candidate.code + "
```

Goal: " + state.goal + "

Return ONLY JSON.";
return [{ json: { state, security_prompt: prompt } }];

// WF-3 parse Security JSON
const llm = $input.first().json;
const prev = $('Build Security prompt').first().json;
let raw = llm.response || JSON.stringify(llm);
let cleaned = (raw||'').trim();
if (cleaned.startsWith('```')) { const lines = cleaned.split('\n'); if (lines[0].startsWith('```')) lines.shift(); if (lines[lines.length-1].startsWith('```')) lines.pop(); cleaned = lines.join('\n'); }
let parsed;
try {
  const s = cleaned.indexOf('{'); const e = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(s, e+1));
} catch(e) { throw new Error(`Security parse failed: ${e.message} raw: ${cleaned.slice(0,500)}`); }
const state = JSON.parse(JSON.stringify(prev.state));
state.audit = state.audit || { security_pass: true, edge_case_pass: true, objections: [] };
state.audit.security_pass = !!parsed.security_pass;
state.audit.objections = (state.audit.objections||[]).concat(parsed.objections||[]);
// stash security result for next step
return [{ json: { state, security_raw: parsed } }];

// WF-3 Critic prompt builder
const prev = $input.first().json;
const state = prev.state;
let system = '';
try { system = require('fs').readFileSync('/prompts/audit_critic_system.md','utf8'); } catch(e) { system = 'You are the Critic. Output JSON {edge_case_pass, objections, proposed_inputs}.'; }
const prompt = system + "

Candidate code:
```python
" + state.candidate.code + "
```

Input schema: " + JSON.stringify(state.candidate.input_schema) + "

Return ONLY JSON.";
return [{ json: { state, critic_prompt: prompt, security_raw: prev.security_raw } }];

// WF-3 parse Critic JSON + run proposed inputs via WF-5 and set edge_case_pass
const llm = $input.first().json;
const prev = $('Build Critic prompt').first().json;
let raw = llm.response || JSON.stringify(llm);
let cleaned = (raw||'').trim();
if (cleaned.startsWith('```')) { const lines = cleaned.split('\n'); if (lines[0].startsWith('```')) lines.shift(); if (lines[lines.length-1].startsWith('```')) lines.pop(); cleaned = lines.join('\n'); }
let parsed;
try {
  const s = cleaned.indexOf('{'); const e = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(s, e+1));
} catch(e) { throw new Error(`Critic parse failed: ${e.message} raw: ${cleaned.slice(0,500)}`); }
const state = JSON.parse(JSON.stringify(prev.state));
state.audit = state.audit || { security_pass: true, edge_case_pass: true, objections: [] };
// Merge critic verdict
state.audit.edge_case_pass = !!parsed.edge_case_pass;
state.audit.objections = (state.audit.objections||[]).concat(parsed.objections||[]);
// Store proposed inputs for actual execution via WF-5 (done in next node or by Orchestrator)
state.audit.proposed_inputs = parsed.proposed_inputs || [];
state.audit.critic_raw = parsed;
return [{ json: state }];
